# rclone remote ziro_s3 (used by `ziroctl backup create --remote ziro_s3:ziro-backups`).
RCLONE_CONFIG_ZIRO_S3_TYPE=s3
RCLONE_CONFIG_ZIRO_S3_PROVIDER=Other
RCLONE_CONFIG_ZIRO_S3_ENDPOINT=http://127.0.0.1:{{setting.port}}
RCLONE_CONFIG_ZIRO_S3_REGION=garage
RCLONE_CONFIG_ZIRO_S3_FORCE_PATH_STYLE=true
RCLONE_CONFIG_ZIRO_S3_ACCESS_KEY_ID=GK{{secret.key_id}}
RCLONE_CONFIG_ZIRO_S3_SECRET_ACCESS_KEY={{secret.key_secret}}
